CREATE TABLE IF NOT EXISTS admin_operations_schema_migrations (version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_work_items (id TEXT PRIMARY KEY,source_system TEXT NOT NULL CHECK (source_system IN ('MARKETPLACE','EXCHANGE','SUPPLY_PILOT','ADMIN')),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,work_type TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,status TEXT NOT NULL CHECK (status IN ('OPEN','CLAIMED','WAITING','RESOLVED','CANCELLED')),priority TEXT NOT NULL CHECK (priority IN ('LOW','NORMAL','HIGH','CRITICAL')),assignee_principal_id TEXT,due_at TEXT,metadata_json TEXT NOT NULL,created_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS admin_work_items_queue_idx ON admin_work_items(status,priority,due_at,created_at DESC);
CREATE INDEX IF NOT EXISTS admin_work_items_entity_idx ON admin_work_items(source_system,entity_type,entity_id,created_at DESC);
CREATE TABLE IF NOT EXISTS admin_approvals (id TEXT PRIMARY KEY,approval_type TEXT NOT NULL CHECK (approval_type='REFUND'),source_system TEXT NOT NULL CHECK (source_system IN ('EXCHANGE','SUPPLY_PILOT')),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK (amount_cents>0),currency TEXT NOT NULL CHECK (currency='CNY'),business_expected_version INTEGER NOT NULL CHECK (business_expected_version>0),status TEXT NOT NULL CHECK (status IN ('PENDING','APPROVED','REJECTED','CANCELLED')),requested_by TEXT NOT NULL,request_reason TEXT NOT NULL,decided_by TEXT,decision_reason TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,decided_at TEXT,CHECK (status='PENDING' OR (decided_by IS NOT NULL AND decision_reason IS NOT NULL AND decided_at IS NOT NULL)),CHECK (decided_by IS NULL OR decided_by<>requested_by));
CREATE INDEX IF NOT EXISTS admin_approvals_queue_idx ON admin_approvals(approval_type,status,created_at DESC);
CREATE TABLE IF NOT EXISTS admin_audit_events (id TEXT PRIMARY KEY,actor_principal_id TEXT NOT NULL,source_system TEXT NOT NULL CHECK (source_system IN ('MARKETPLACE','EXCHANGE','SUPPLY_PILOT','ADMIN')),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,reason TEXT NOT NULL,payload_digest TEXT NOT NULL,occurred_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS admin_audit_events_entity_idx ON admin_audit_events(source_system,entity_type,entity_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS admin_audit_events_actor_idx ON admin_audit_events(actor_principal_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS admin_principal_projection (id TEXT PRIMARY KEY,display_name TEXT NOT NULL,status TEXT NOT NULL CHECK (status IN ('ACTIVE','SUSPENDED')),roles_json TEXT NOT NULL,permissions_json TEXT NOT NULL,projected_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_role_projection (code TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL CHECK (status IN ('ACTIVE','RETIRED')),permissions_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,projected_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_command_receipts (actor_principal_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,command_type TEXT NOT NULL,payload_hash TEXT NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(actor_principal_id,idempotency_key));
CREATE TABLE IF NOT EXISTS admin_entity_ownership (source_system TEXT NOT NULL CHECK (source_system IN ('MARKETPLACE','EXCHANGE','SUPPLY_PILOT','ADMIN')),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,organization_id TEXT NOT NULL,account_id TEXT NOT NULL,legacy_actor_id TEXT,bound_by_principal_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(source_system,entity_type,entity_id));
CREATE INDEX IF NOT EXISTS admin_entity_ownership_org_idx ON admin_entity_ownership(organization_id,source_system,entity_type,updated_at DESC);
INSERT OR IGNORE INTO admin_operations_schema_migrations(version,applied_at) VALUES(1,CURRENT_TIMESTAMP);
